import numpy as np
from itertools import permutations

n = 12

def check_qg3(grid, i, j):
    """Check QG3 constraint for position (i,j)"""
    a = grid[i][j]
    b = grid[j][i]
    if a is None or b is None:
        return True
    if grid[a][b] is None:
        return True
    return grid[a][b] == i

def is_valid_placement(grid, row, col, val):
    """Check if placing val at (row, col) is valid"""
    # Check row
    if val in grid[row]:
        return False
    # Check column
    if any(grid[r][col] == val for r in range(n)):
        return False
    # Check idempotent
    if row == col and val != row:
        return False
    return True

# Let's try a different approach - use the known structure
# For QG3 quasigroups of order 12, they're related to specific algebraic structures

# Actually, let's try using pycosat or a more efficient approach
# Let's try constraint propagation with backtracking

def solve_qg3():
    # Initialize grid with None
    grid = [[None]*n for _ in range(n)]

    # Set diagonal (idempotent)
    for i in range(n):
        grid[i][i] = i

    # Track available values for each row and column
    row_avail = [set(range(n)) - {i} for i in range(n)]
    col_avail = [set(range(n)) - {i} for i in range(n)]

    # Remove diagonal values
    for i in range(n):
        row_avail[i].discard(i)
        col_avail[i].discard(i)

    def place(r, c, v):
        grid[r][c] = v
        row_avail[r].discard(v)
        col_avail[c].discard(v)

    def unplace(r, c, v):
        grid[r][c] = None
        row_avail[r].add(v)
        col_avail[c].add(v)

    def get_next_cell():
        # Find cell with minimum remaining values (MRV heuristic)
        best = None
        best_count = n + 1
        for r in range(n):
            for c in range(n):
                if grid[r][c] is None:
                    avail = row_avail[r] & col_avail[c]
                    if r == c:
                        avail = {r} if r in avail else set()
                    cnt = len(avail)
                    if cnt < best_count:
                        best_count = cnt
                        best = (r, c)
                        if cnt == 0:
                            return best, set()
        if best is None:
            return None, None
        r, c = best
        return best, row_avail[r] & col_avail[c]

    def check_qg3_constraints():
        """Check all QG3 constraints that can be checked"""
        for i in range(n):
            for j in range(n):
                a = grid[i][j]
                b = grid[j][i]
                if a is not None and b is not None and grid[a][b] is not None:
                    if grid[a][b] != i:
                        return False
        return True

    call_count = [0]

    def backtrack():
        call_count[0] += 1
        if call_count[0] % 100000 == 0:
            print(f"Calls: {call_count[0]}")

        cell, avail = get_next_cell()
        if cell is None:
            return True  # All filled

        r, c = cell

        for v in sorted(avail):
            place(r, c, v)

            # Quick QG3 check
            valid = True
            # Check constraints involving (r,c)
            # x[r][c] = v, so check x[v][x[c][r]] = r if x[c][r] is known
            xrc = v
            xcr = grid[c][r]
            if xcr is not None:
                if grid[xrc][xcr] is not None and grid[xrc][xcr] != r:
                    valid = False
                # Also check: x[x[c][r]][x[r][c]] = c
                # i.e., x[xcr][xrc] = c
                if valid and grid[xcr][xrc] is not None and grid[xcr][xrc] != c:
                    valid = False

            if valid:
                if backtrack():
                    return True

            unplace(r, c, v)

        return False

    if backtrack():
        return grid
    return None

print("Starting backtracking search...")
result = solve_qg3()
if result:
