# Let's use pysat to encode this as a SAT problem
# Variables: x[i][j][v] = True iff grid[i][j] = v
# This gives 12*12*12 = 1728 boolean variables

from pysat.solvers import Glucose3
from pysat.formula import CNF

n = 12

# Variable encoding: var(i, j, v) = i*n*n + j*n + v + 1 (1-indexed)
def var(i, j, v):
    return i*n*n + j*n + v + 1

clauses = []

# At least one value per cell
for i in range(n):
    for j in range(n):
        clauses.append([var(i, j, v) for v in range(n)])

# At most one value per cell
for i in range(n):
    for j in range(n):
        for v1 in range(n):
            for v2 in range(v1+1, n):
                clauses.append([-var(i, j, v1), -var(i, j, v2)])

# Each value appears at least once in each row
for i in range(n):
    for v in range(n):
        clauses.append([var(i, j, v) for j in range(n)])

# Each value appears at most once in each row
for i in range(n):
    for v in range(n):
        for j1 in range(n):
            for j2 in range(j1+1, n):
                clauses.append([-var(i, j1, v), -var(i, j2, v)])

# Each value appears at least once in each column
for j in range(n):
    for v in range(n):
        clauses.append([var(i, j, v) for i in range(n)])

# Each value appears at most once in each column
for j in range(n):
    for v in range(n):
        for i1 in range(n):
            for i2 in range(i1+1, n):
                clauses.append([-var(i1, j, v), -var(i2, j, v)])

# Idempotent: x[i][i] = i
for i in range(n):
    clauses.append([var(i, i, i)])

print(f"Basic constraints: {len(clauses)} clauses")

# QG3: x[x[i][j]][x[j][i]] = i
# If x[i][j] = a and x[j][i] = b, then x[a][b] = i
# Encoding: var(i,j,a) AND var(j,i,b) => var(a,b,i)
# Equivalently: NOT var(i,j,a) OR NOT var(j,i,b) OR var(a,b,i)

for i in range(n):
    for j in range(n):
        for a in range(n):
            for b in range(n):
                # If x[i][j]=a and x[j][i]=b then x[a][b]=i
                clauses.append([-var(i, j, a), -var(j, i, b), var(a, b, i)])

print(f"After QG3 constraints: {len(clauses)} clauses")

# Solve
solver = Glucose3()
for clause in clauses:
    solver.add_clause(clause)

print("Solving...")
result = solver.solve()
print(f"Result: {result}")

if result:
